<script lang="ts">
 import {dayKey,monthDays,onDay,type Event} from './month';
 import {CALENDAR_DOMAIN_ORDER,calendarDomain,calendarDomainClass,calendarDomainLabel} from './domain';
 let {events}:{events:Event[]}=$props();
 const today=dayKey(new Date());
 let selected=$state(today),month=$state(today.slice(0,7));
 const days=$derived(monthDays(month));
 const entries=$derived(events.filter(e=>onDay(e,selected)).sort((a,b)=>(a.start.dateTime??a.start.date??'').localeCompare(b.start.dateTime??b.start.date??'')));
 const visibleDomains=$derived(CALENDAR_DOMAIN_ORDER.filter(domain=>events.some(event=>event.status!=='cancelled'&&calendarDomain(event.domain)===domain)));
 const title=$derived(new Intl.DateTimeFormat('de-CH',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(month+'-01T12:00:00Z')));
 function move(n:number){const d=new Date(month+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);month=d.toISOString().slice(0,7);selected=month+'-01';}
 function time(value?:string){return value?new Intl.DateTimeFormat('de-CH',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Zurich'}).format(new Date(value)):'';}
 function responseLabel(value:string){return value==='accepted'?'zugesagt':value==='declined'?'abgesagt':value==='tentative'?'vielleicht':'offen';}
</script>
<div class="calendar">
 <div class="month-bar"><h2 aria-live="polite">{title}</h2><div><button aria-label="Vorheriger Monat" onclick={()=>move(-1)}>‹</button><button onclick={()=>{month=today.slice(0,7);selected=today;}}>Heute</button><button aria-label="Nächster Monat" onclick={()=>move(1)}>›</button></div></div>
 {#if visibleDomains.length}<div class="legend" aria-label="Kalenderdomänen">{#each visibleDomains as domain}<span class={calendarDomainClass(domain)}><i aria-hidden="true"></i>{calendarDomainLabel(domain)}</span>{/each}</div>{/if}
 <div class="weekdays" aria-hidden="true">{#each ['Mo','Di','Mi','Do','Fr','Sa','So'] as day}<span>{day}</span>{/each}</div>
 <div class="grid">{#each days as day}{@const items=events.filter(e=>onDay(e,day))}<button class="day" class:outside={!day.startsWith(month)} class:today={day===today} class:selected={day===selected} aria-pressed={day===selected} aria-label={`${day}: ${items.length} Termine`} onclick={()=>selected=day}><span class="number">{Number(day.slice(8))}</span><span class="items">{#each items.slice(0,3) as event}<span class={`event ${calendarDomainClass(event.domain)}`} title={`${calendarDomainLabel(event.domain)} · ${event.summary??'Ohne Titel'}`}>{time(event.start.dateTime)} {event.summary??'Ohne Titel'}</span>{/each}{#if items.length>3}<span class="more">+{items.length-3} weitere</span>{/if}</span>{#if items.length}<span class="count">{items.length} <span class="count-label">Termine</span></span>{/if}</button>{/each}</div>
 <div class="day-details"><h3>{new Intl.DateTimeFormat('de-CH',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(selected+'T12:00:00Z'))}</h3>{#each entries as event}<article class={calendarDomainClass(event.domain)}><span class="time">{event.start.dateTime?time(event.start.dateTime)+' – '+time(event.end.dateTime):'Ganztägig'}</span><div><span class="domain-label">{calendarDomainLabel(event.domain)}</span><strong>{event.summary??'Ohne Titel'}</strong>{#if event.location}<p>{event.location}</p>{/if}{#if event.inviteeResponses?.length}<div class="responses" aria-label="Einladungsantworten">{#each event.inviteeResponses as response}<span class:accepted={response.responseStatus==='accepted'} class:declined={response.responseStatus==='declined'} class:tentative={response.responseStatus==='tentative'}><i aria-hidden="true"></i>{response.role} · {responseLabel(response.responseStatus)}</span>{/each}</div>{/if}</div></article>{:else}<p class="empty">Keine Termine.</p>{/each}</div>
</div>
<style>
 .calendar{border:1px solid var(--color-border);border-radius:12px;background:var(--color-card);overflow:hidden}.month-bar{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:18px}.month-bar h2{font-size:20px;font-weight:600;margin:0}.month-bar>div{display:flex;gap:6px}button{font:inherit;color:inherit;cursor:pointer}.month-bar button{min-height:40px;min-width:40px;padding:6px 12px;border:1px solid var(--color-border);border-radius:6px;background:var(--color-card)}.legend{display:flex;flex-wrap:wrap;gap:8px 15px;padding:0 18px 14px;color:var(--color-muted-foreground);font-size:11px}.legend span{display:inline-flex;align-items:center;gap:6px}.legend i{width:8px;height:8px;border-radius:50%;background:var(--event-accent)}.weekdays,.grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.weekdays{background:var(--color-muted);color:var(--color-muted-foreground);text-align:center;font-size:12px;padding:9px 0}.day{min-width:0;min-height:112px;display:flex;flex-direction:column;gap:6px;text-align:left;padding:8px;border:0;border-top:1px solid var(--color-border);border-right:1px solid var(--color-border);background:var(--color-card)}.day:nth-child(7n){border-right:0}.outside{color:var(--color-muted-foreground);background:var(--color-background)}.day.selected{box-shadow:inset 0 0 0 2px var(--color-foreground);background:var(--color-muted)}.number{display:grid;place-items:center;width:26px;height:26px;font-size:13px}.today .number{background:var(--color-foreground);color:var(--color-background);border-radius:50%}.items{display:grid;gap:3px;width:100%}.event{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;padding:3px 5px;border-radius:4px;background:color-mix(in srgb,var(--event-accent) 14%,var(--color-card));border-left:3px solid var(--event-accent)}.more{font-size:11px}.count{display:none}.day-details{padding:20px;border-top:1px solid var(--color-border)}h3{font-size:16px;margin:0 0 14px}article{display:flex;gap:20px;padding:12px 10px;border-top:1px solid var(--color-border);border-left:3px solid var(--event-accent)}.time{min-width:100px;color:var(--color-muted-foreground);font-size:13px}.domain-label{display:block;color:var(--event-accent);font:600 10px ui-monospace,monospace;letter-spacing:.08em;text-transform:uppercase;margin-bottom:4px}article strong{display:block}article p,.empty{color:var(--color-muted-foreground);font-size:13px;margin:6px 0}.responses{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.responses span{display:inline-flex;align-items:center;gap:5px;padding:3px 7px;border:1px solid var(--color-border);border-radius:999px;color:var(--color-muted-foreground);font-size:10px}.responses i{width:6px;height:6px;border-radius:50%;background:#a1a1aa}.responses .accepted i{background:#10b981}.responses .declined i{background:#ef4444}.responses .tentative i{background:#f59e0b}.domain-immo{--event-accent:#3b82f6}.domain-job{--event-accent:#8b5cf6}.domain-shopping{--event-accent:#f59e0b}.domain-finance{--event-accent:#10b981}.domain-kontakt{--event-accent:#ec4899}.domain-werbung{--event-accent:#f97316}.domain-system{--event-accent:#64748b}.domain-unsorted{--event-accent:#a1a1aa}button:focus-visible{outline:2px solid var(--color-foreground);outline-offset:-2px}@media(max-width:640px){.month-bar{padding:12px}.legend{padding:0 12px 10px}.month-bar h2{font-size:16px}.month-bar button{padding:6px 8px}.day{min-height:64px;padding:5px}.items{display:none}.count{display:block;font-size:10px}.count-label{display:none}.day-details{padding:16px}article{gap:10px}.time{min-width:85px}}
</style>
